        'train': 'train.csv',
        'validation': 'val.csv',
        'test': 'test.csv'
    }
    def load_dataset(self, split):
        return datasets.load_dataset('csv', data_files={split: os.path.join(self.file_prefix, f"mrpc_csv/{self.split_to_file_name[split]}")}, column_names=['sentence1', 'sentence2', 'label', 'idx'])[split]
    def preprocessor(self, example, add_prefix=True, add_vb=False):
        src_texts = ["sentence1:", example['sentence1'], "sentence2:", example['sentence2']]
        tgt_texts = [str(example['label'])]
        if add_vb:
            verbalizer = "{ 0 : not equivalent, 1 : equivalent }"
        else:
            verbalizer = ""
        return self.seq2seq_format(src_texts, tgt_texts, add_prefix, verbalizer=verbalizer)

if hasattr(globals(), 'AutoTask') and hasattr(AutoTask, 'task_dict'):
    AutoTask.task_dict['mrpc_csv'] = MRPC_CSV

