# Script to create small splits (first 10) for train/valid/test for TEAM MCQA
for split in ["train", "valid", "test"]:
    with open(f"{split}.jsonl", "r") as jin, open(f"{split}-small.jsonl", "w") as jout:
        for i, line in enumerate(jin):
            if i == 10:
                break
            jout.write(line)
    # Labels for train/valid
    if split != "test":
        with open(f"{split}-labels.lst", "r") as lin, open(f"{split}-small-labels.lst", "w") as lout:
            for i, line in enumerate(lin):
                if i == 10:
                    break
                lout.write(line)
    else:
        # For test, create dummy label file of zeroes
        with open(f"{split}-small-labels.lst", "w") as lout:
            for _ in range(10):
                lout.write("0\n")

